using FamilyVeda.Domain.Portal;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace FamilyVeda.Infrastructure.Persistence.Configurations;

internal sealed class FamilyJoinRequestConfiguration : IEntityTypeConfiguration<FamilyJoinRequest>
{
    public void Configure(EntityTypeBuilder<FamilyJoinRequest> builder)
    {
        builder.ToTable("family_join_requests");
        builder.HasKey(x => x.Id);
        builder.Property(x => x.RelationshipType).HasMaxLength(40).IsRequired();
        builder.Property(x => x.Message).HasMaxLength(280);
        builder.Property(x => x.Status).HasConversion<string>().HasMaxLength(20);
        builder.HasOne(x => x.Family).WithMany().HasForeignKey(x => x.FamilyId).OnDelete(DeleteBehavior.Cascade);
        builder.HasOne(x => x.RequestingUser).WithMany().HasForeignKey(x => x.RequestingUserId).OnDelete(DeleteBehavior.Restrict);
        builder.HasIndex(x => new { x.FamilyId, x.Status });
        builder.HasIndex(x => new { x.RequestingUserId, x.CreatedAt });
    }
}

internal sealed class FamilyDoctorRequestConfiguration : IEntityTypeConfiguration<FamilyDoctorRequest>
{
    public void Configure(EntityTypeBuilder<FamilyDoctorRequest> builder)
    {
        builder.ToTable("family_doctor_requests");
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Message).HasMaxLength(280);
        builder.Property(x => x.Status).HasConversion<string>().HasMaxLength(20);
        builder.HasOne(x => x.Family).WithMany().HasForeignKey(x => x.FamilyId).OnDelete(DeleteBehavior.Cascade);
        builder.HasOne(x => x.Doctor).WithMany().HasForeignKey(x => x.DoctorId).OnDelete(DeleteBehavior.Cascade);
        builder.HasIndex(x => new { x.DoctorId, x.Status });
        builder.HasIndex(x => new { x.FamilyId, x.Status });
    }
}

internal sealed class AppointmentConfiguration : IEntityTypeConfiguration<Appointment>
{
    public void Configure(EntityTypeBuilder<Appointment> builder)
    {
        builder.ToTable("appointments");
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Reason).HasMaxLength(200).IsRequired();
        builder.Property(x => x.DoctorNote).HasMaxLength(500);
        builder.Property(x => x.Status).HasConversion<string>().HasMaxLength(20);
        builder.HasOne(x => x.Member).WithMany().HasForeignKey(x => x.MemberId).OnDelete(DeleteBehavior.Cascade);
        builder.HasOne(x => x.Doctor).WithMany().HasForeignKey(x => x.DoctorId).OnDelete(DeleteBehavior.Cascade);
        builder.HasIndex(x => new { x.DoctorId, x.StartsAt });
        builder.HasIndex(x => new { x.MemberId, x.StartsAt });
    }
}

internal sealed class PortalNotificationConfiguration : IEntityTypeConfiguration<PortalNotification>
{
    public void Configure(EntityTypeBuilder<PortalNotification> builder)
    {
        builder.ToTable("notifications");
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Type).HasMaxLength(60).IsRequired();
        builder.Property(x => x.Title).HasMaxLength(120).IsRequired();
        builder.Property(x => x.Body).HasMaxLength(400).IsRequired();
        builder.Property(x => x.LinkPath).HasMaxLength(200);
        builder.HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
        builder.HasIndex(x => new { x.UserId, x.CreatedAt });
    }
}
